    transfer: [
      B.text('070_t_situation', 'Kirjutamine ja rääkimine (eksami vormis)', 'Su sõber Liis kirjutab raamatut „Uued eestlased” ja palub sinu lugu. See leht on nagu Harno B1 eksami kirjutamise ja rääkimise osa. Tee kõik ilma abita.'),
      B.reading('070_t_read', 'Loe sõbra kirja.', 'Loe ja vasta küsimustele.', 'Kiri Liisilt',
        'Tere! Nagu sa tead, kirjutan ma raamatut inimestest, kes on Eestisse kolinud. Ma olen juba intervjueerinud kakskümmend inimest. Nad on tulnud Ukrainast, Indiast, Brasiiliast ja mujalt. Iga lugu on erinev: mõned on siin elanud kolmkümmend aastat, mõned ainult ühe aasta. Ma tahaksin väga ka sinu lugu. Palun kirjuta mulle umbes sada kuni sada kakskümmend sõna. Kirjuta, mida oled Eestis kogenud. Näiteks, kas oled käinud saunas, laulupeol või rabas? Ja jutusta üks päev, mida sa kunagi ei unusta. Kirjuta, mis juhtus, mis tunne sul oli ja mida sa õppisid. Kui soovid, võime ka kohtuda ja rääkida. Siis salvestan ma meie vestluse ja kirjutan loo ise. Raamat ilmub järgmisel sügisel ja iga autor saab ühe raamatu kingituseks. Ma loodan, et see raamat aitab teistel uutel eestlastel end siin vähem üksikuna tunda. Raamatu jaoks otsin ma ka fotosid, näiteks sinu esimesest päevast Eestis või mõnest tähtsast sündmusest. Kui sul on selline pilt, saada see mulle julgelt e-postiga. Kõik fotod tagastan ma sulle kohe pärast raamatu ilmumist. Raamatu esitlus toimub Tallinna keskraamatukogus ja kõik autorid on sinna oodatud. Aitäh juba ette! Kui sa ei taha oma pärisnime raamatus näha, kirjuta mulle sellest. Siis kasutan ma teist nime. Kohtumiseni ja ilusat päeva sulle! Sinu sõber Liis.',
        [['Millest Liisi raamat räägib?', 'inimestest, kes on Eestisse kolinud|Eestisse kolinud inimestest|uutest eestlastest'], ['Mitut inimest on ta intervjueerinud?', 'kahtkümmend|kakskümmend|20'], ['Kui pikk peab lugu olema?', 'sada kuni sada kakskümmend sõna|100–120 sõna|100-120 sõna'], ['Mida saab teha, kui ei taha lugu ise kirjutada?', 'kohtuda ja rääkida|kohtuda|rääkida'], ['Mida autor saab?', 'ühe raamatu kingituseks|raamatu'], ['Miks kirjutab Liis sinu arvates sellist raamatut?', 'et uued eestlased tunneksid end vähem üksikuna|et aidata uusi eestlasi']]),
      B.transformation('070_t_trans', 'Vali aeg.', 'Kirjuta lause antud sõnaga.', [['Ma käin saunas. (kogemus)', 'olen', 'Ma olen saunas käinud.|Ma olen käinud saunas.'], ['Ma käin laulupeol. (2019)', 'käisin', '2019. aastal käisin ma laulupeol.|Ma käisin 2019. aastal laulupeol.|2019. aastal ma käisin laulupeol.'], ['Ma ei käi rabas. (kunagi)', 'ei ole kunagi', 'Ma ei ole kunagi rabas käinud.|Ma ei ole rabas kunagi käinud.'], ['Mul oli raske. (alguses)', 'alguses', 'Alguses oli mul raske.|Mul oli alguses raske.'], ['Ma õppisin palju. (kogemus)', 'olen', 'Ma olen palju õppinud.'], ['Me kolisime. Me müüsime auto. (enne)', 'enne', 'Enne kolimist müüsime me auto.|Enne kolimist müüsime auto.']]),
      B.writing('070_t_note', 'Kirjutamine 1. Teade Liisile (umbes 70–80 sõna).', 'Sa ei saa laupäeval intervjuule tulla. Kirjuta Liisile 8–10 lausega: miks, uus aeg, kes saaks sinu asemel rääkida, sinu kontakt.', [8, 10], ['kahjuks', 'sest', 'kas sobiks', 'helista'], 3),
      B.letter('070_t_letter', 'Kirjutamine 2. Lugu raamatusse.', 'Kirjuta lugu „Päev, mida ma ei unusta”: millal ja kus, mis juhtus, mis tunne oli, mida õppisid.', 'Päev, mida ma ei unusta', 'Autor:', [90, 120]),
      B.rubric('070_t_rubric', 'Punktid: kirjutamine 20, rääkimine 20.', 'Õpetaja annab punktid. Eesmärk: vähemalt 12 kummaski.', ['Kirjutamine 1 (0–8): kõik neli punkti, umbes 70–80 sõna.', 'Kirjutamine 2 (0–12): sündmus, tunne, põhjus, järeldus; lihtminevik ja täisminevik; umbes 100 sõna.', 'Rääkimine 1 (0–6): vastab küsimustele seotult.', 'Rääkimine 2 (0–7): arutleb ja jõuab kokkuleppele.', 'Rääkimine 3 (0–7): küsib ja annab telefonis kogu info.']),
      B.speaking('070_t_mono', 'Rääkimine 1. Küsimused teemalehelt.', 'Õpetaja küsib, sina vastad. Räägi iga küsimuse kohta umbes pool minutit.', ['Mida oled Eestis kogenud, mida sinu kodumaal ei ole?', 'Mida sa ei ole veel teinud, aga tahaksid teha?'], [90, 150]),
      B.speaking('070_t_agree', 'Rääkimine 2. Jõudke kokkuleppele.', 'Teie keelegrupp teeb ühise väljasõidu. Arutage kahte võimalust ja otsustage koos, kumb on parem.', ['Rabamatk: terve päev looduses, giid, oma toit kaasa, tasuta.', 'Muuseumiekskursioon Tallinnas: kolm tundi, giid räägib eesti keeles, pilet 8 eurot.', 'Mille kasuks te otsustate ja miks?'], [90, 120], ['Minu meelest…', 'Ma olen nõus, aga…', 'Kuidas oleks, kui…?', 'Otsustame siis nii.']),
      B.rolecards('070_t_roles', 'Rääkimine 3. Telefonikõne.', 'Rääkige 4–5 minutit. A helistab muuseumi, B on muuseumi töötaja.',
        'Küsimuste kaart. Helista muuseumi ja küsi grupi kohta: 1) millal on eestikeelne ekskursioon; 2) kui palju pilet maksab; 3) kas grupp saab soodustust; 4) kuidas broneerida.', 'Vastuste kaart. Eestikeelne ekskursioon: laupäeval kell 12. Pilet: 8 eurot. Grupp alates kümnest inimesest: 6 eurot. Broneerimine: telefonil või e-postiga kolm päeva ette.',
        ['Tere, mina olen…', 'Ma sooviksin teada…', 'Kas te saaksite seda korrata?'], ['Linnamuuseum, tere!', 'Jah, see on võimalik…', 'Kas teil on veel küsimusi?']),
    ],
